from collections import Counter

FIXTURE = [
    {"animal": "fox", "x": 2, "y": 1},
    {"animal": "owl", "x": 0, "y": 3},
    {"animal": "fox", "x": 2, "y": 1},
]


def busiest_cell(rows):
    if not rows:
        return None
    tally = Counter((row["x"], row["y"]) for row in rows)
    best = max(tally.values())
    return min(cell for cell, seen in tally.items() if seen == best)


print(busiest_cell(FIXTURE))
